-- ============================================================
-- Modelo de datos: control de flota y costos de mantenimiento
-- Versión pública / anonimizada (ver README y REPORTE_ANONIMIZACION)
-- Generado automáticamente desde los catálogos limpios (Python/pandas)
-- ============================================================

BEGIN;

CREATE TABLE IF NOT EXISTS equipos (
    equipo_id INTEGER PRIMARY KEY,
    clave VARCHAR(50) NOT NULL,
    descripcion TEXT,
    tipo VARCHAR(50),
    es_centro_costo BOOLEAN NOT NULL DEFAULT FALSE,
    activo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS categorias (
    categoria_id INTEGER PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    tipo VARCHAR(20) NOT NULL,
    grupo VARCHAR(30)
);

CREATE TABLE IF NOT EXISTS proveedores (
    proveedor_id INTEGER PRIMARY KEY,
    nombre_normalizado VARCHAR(200) NOT NULL,
    es_persona_fisica BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS movimientos (
    movimiento_id INTEGER PRIMARY KEY,
    fecha DATE,
    anio_origen VARCHAR(20),
    equipo_id INTEGER REFERENCES equipos(equipo_id),
    categoria_id INTEGER REFERENCES categorias(categoria_id),
    proveedor_id INTEGER REFERENCES proveedores(proveedor_id),
    beneficiario VARCHAR(100),
    concepto TEXT,
    cantidad NUMERIC,
    unidad VARCHAR(20),
    precio_unitario NUMERIC,
    subtotal NUMERIC,
    iva NUMERIC,
    total NUMERIC,
    tiene_factura BOOLEAN NOT NULL DEFAULT FALSE,
    medio_pago VARCHAR(50),
    es_reconstruido BOOLEAN NOT NULL DEFAULT FALSE,
    archivo_origen VARCHAR(20),
    hoja_origen VARCHAR(100)
);

CREATE INDEX IF NOT EXISTS idx_movimientos_equipo ON movimientos(equipo_id);
CREATE INDEX IF NOT EXISTS idx_movimientos_categoria ON movimientos(categoria_id);
CREATE INDEX IF NOT EXISTS idx_movimientos_proveedor ON movimientos(proveedor_id);
CREATE INDEX IF NOT EXISTS idx_movimientos_fecha ON movimientos(fecha);





COMMIT;

